%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ SMILe Resampling Routine
%$$$$$$ JCM, current as of 05/10/2018
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ DO NOT EDIT THIS FILE
%$$$$$$ MAKE A COPY OF THIS FILE AND SAVE IT TO YOUR HARD DRIVE
%$$$$$$ THEN, AND ONLY THEN, MAKE IT WORK FOR YOUR UNIQUE SETTINGS
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ This routine is performs either a true bootstrap estimation of the mean and computes 95% confidence intervals, or performs a hybrid bootstrap / Monte Carlo simulation of datasets. 
%$$$$$$ 
%$$$$$$ There are no external dependencies other that EEGLAB
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ CIboot = bootCI(EEG,opts);
%$$$$$$ 
%$$$$$$ output is the bootstrapped mean timeseries with 95% CI 
%$$$$$$
%$$$$$$ A unique CI is created for every electrode
%$$$$$$ 
%$$$$$$ EEG is an EEGLAB structure with preprocessed, epoched data
%$$$$$$ or some other 3-D structure in the form of channels x time x trials
%$$$$$$
%$$$$$$ opts - a structure with the following fields
%$$$$$$ .ntrials - how many trials of the original data (in percentge form)
%$$$$$$     e.g., 0.2 for 20% of the data - to be included in each
%$$$$$$     sampling iteration 
%$$$$$$     default is 20%
%$$$$$$ .ntimes - how many resampling iterations to run
%$$$$$$     default is 2000
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Should one want to use this methodology as a means of computing a
%$$$$$$ difference wave on the bootstraped data from two conditions and 
%$$$$$$ then computing a 95% CI:
%$$$$$$ 
%$$$$$$ mnA = mean(EEGa,1);
%$$$$$$ sdA = std(EEGa,1) / sqrt(ntrials);
%$$$$$$ mnB = mean(EEGb,1);
%$$$$$$ sdB = std(EEGb,1) / sqrt(ntrials);
%$$$$$$ 
%$$$$$$ Compute the difference wave and the standard deviation:
%$$$$$$ mnD = mnA - mnB;
%$$$$$$ sdmnD = (sdmnA.^2 + sdmnB.^2);
%$$$$$$
%$$$$$$ Apply CI for visualization
%$$$$$$ plot(mnD);
%$$$$$$ hold on
%$$$$$$ plot(mn + 2*sdmn);
%$$$$$$ plot(mn - 2*sdmn);
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Start file
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
function CIboot = bootCI(EEG,opts);

tstart = tic;
fprintf('##################################################################################################################\n\n');
fprintf('Beginning PreProcessing Routine ----- '); disp(datestr(now))
fprintf('\n')
fprintf('##################################################################################################################\n\n');

%% 
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Declare data, checking for an EEG structure
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
try 
data = EEG.data;

catch
data = EEG;
        
end

%% 
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Grab the dimensions of the data for later use
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
dims = size(data);

%% 
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Declare settings, if no "opts" structure is passed in
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
if ~exist("opts", 'var');
opts.ntimes = 2000;
opts.ntrials = floor(dims(3) * .20);

elseif exist("opts", 'var');
ntimes = opts.ntimes;
ntrials = floor(dims(3) * .20);

end

%% 
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Start it
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
boot = zeros(dims(1), dims(2), ntimes);

for k = 1:ntimes;
    rsamp = randsample(1:dims(3),ntrials,1);
    tmpboot = data(:,:,rsamp);
    boot(:,:,k) = squeeze(mean(tmpboot,3));
    clear tmpboot

end

%% 
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Initialize output and calculate the CIs and the mean of the
%$$$$$$ bootstrapped sample
%$$$$$$
%$$$$$$ First step is to traspose the data to get the dimensions to work
%$$$$$$ 
%$$$$$$ Next, the transposed data are sorted
%$$$$$$ 
%$$$$$$ Finally, the CIs are calculated, along with the mean
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
ciL = [];
ciU = [];
mnA = [];
sdmn = [];
SIM = [];

for k = 1:dims(1);
tboot = transpose(squeeze(boot(k,:,:)));
sboot = sort(tboot);
ciL(k,:) = sboot(floor(0.025*size(tboot,1)),:);
ciU(k,:) = sboot(floor(0.975*size(tboot,1)),:);
mnA(k,:) = mean(tboot,1);
sd(k,:) = std(tboot,1);
sdmn(k,:) = sd(k,:)./sqrt(ntrials);
clear sboot tboot

end

%% 
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Do it
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
CIboot = struct('mnA', mnA, 'sdmn', sdmn, 'ciL', ciL, 'ciU', ciU);

%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Print report
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
telapsed = toc(tstart);
telapsed = telapsed / 60;
fprintf('##################################################################################################################\n\n');
fprintf('All files processed ... time elapsed is %s minutes.\n\n', telapsed);
disp(datestr(now) )
fprintf('##################################################################################################################\n\n');

end

%% 
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ End case 1, start case 2
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$